use std::collections::HashMap;
use std::collections::LinkedList;

pub struct LruCache<K, V> {
    capacity: usize,
    // key -> node in the doubly-linked list (order: front = most recent, back = least recent)
    map: HashMap<K, LinkedListNode<K, V>>,
    // doubly-linked list of nodes
    list: LinkedList<LinkedListNode<K, V>>,
}

// A node in the doubly-linked list.
struct LinkedListNode<K, V> {
    key: K,
    value: V,
    prev: Option<NonNull<LinkedListNode<K, V>>>,
    next: Option<NonNull<LinkedListNode<K, V>>>,
}

// SAFETY: We only ever access a node through the map/list, which keeps the
// invariant that every node is reachable. We never drop a node while it's
// still linked.
